import{p as e,b as o,C as p}from"./vue-vendor-de6b2611.js";const c={class:"markdown-body"},d=p('<h1>R1 产品文档</h1><h2>硬件设计</h2><p><img src="https://s2.loli.net/2023/03/18/8kR6c5wLIAbF2ox.jpg" alt="8kR6c5wLIAbF2ox"></p><blockquote><p>从零到一，独家设计。 因商务合作关系，部分消费者可能会看到其他冠名的产品 <em>(非硬酷渠道产品，不享受本公司售后)</em>。</p></blockquote><ul><li><p>CPU：赛扬N5105、奔腾银牌N6005</p></li><li><p>内存：LPDDR4 双通道，单颗粒8GB (<strong><code>16GB为双内存颗粒双通道</code></strong>)</p></li><li><p>网卡：4 x Intel i226-V</p></li><li><p>硬盘：1 x<strong>M.2 2242 NVMe （PCIe3.0x2速率）。</strong>- 显示：1 x HDMI 2.0 4K 60Hz视频输出</p></li><li><p>USB： 2 x USB 3.1 Gen2；1 x USB-C 3.1 Gen2；</p></li><li><p>TF：1 x TF Card Reader**（支持启动）已测试：Linux及其分支均(<code>OpenWRT, pfsense, OPNSense</code>)可启动，Windows需以<code>WinToGo方式</code>启动**- 散热：主动散热<strong>2023年后已全面升级到<code>铜管散热器+滚静音风扇</code>，已无噪音困扰！放心选购！</strong>- 电源：标配 12V 2.5A 30W DC电源 （<code>标配DC圆头转USB-C口直通线</code>）</p></li></ul><blockquote><p>特殊定制C口 12V DC电源，请勿使用此标配DC电源给其他设备供电，以免烧坏其他电子设备！否则后果自负！</p></blockquote><ul><li>尺寸：7.5 x 7.5 x 4.8cm**(方寸之间，尽享乐趣)**## 结构设计**</li></ul><p><img src="https://s2.loli.net/2023/03/19/EwsZmybJ2Og56xT.png" alt="EwsZmybJ2Og56xT"></p><p><img src="https://s2.loli.net/2023/03/18/dqBHfG9aSomIb8w.png" alt="测试"></p><p><img src="https://s2.loli.net/2023/03/18/SNbRW7GtLgYxJ3f.png" alt="SNbRW7GtLgYxJ3f"></p><p><img src="https://s2.loli.net/2023/03/18/SGEr9LewCYRvkmP.png" alt="SGEr9LewCYRvkmP"></p><p><img src="https://s2.loli.net/2023/03/18/ZMN7LtJoKlAU2TF.png" alt="ZMN7LtJoKlAU2TF"></p><h2>系统兼容性</h2><table><thead><tr><th><img src="https://www.ikoolcore.com/cdn/shop/files/pfsense.webp?v=1704086584&amp;width=200" alt="pfsense.webp?v=1704086584&amp;width=200"></th><th><img src="https://www.ikoolcore.com/cdn/shop/files/OPNsense.webp?v=1704086651&amp;width=200" alt="OPNsense.webp?v=1704086651&amp;width=200"></th><th><img src="https://www.ikoolcore.com/cdn/shop/files/openwrt.webp?v=1704085927&amp;width=200" alt="openwrt.webp?v=1704085927&amp;width=200"></th><th><img src="https://www.ikoolcore.com/cdn/shop/files/untangle-v.webp?v=1704086344&amp;width=200" alt="untangle-v.webp?v=1704086344&amp;width=200"></th><th><img src="https://www.ikoolcore.com/cdn/shop/files/XCP-NG.webp?v=1704086432&amp;width=200" alt="XCP-NG.webp?v=1704086432&amp;width=200"></th><th><img src="https://www.ikoolcore.com/cdn/shop/files/panabit.webp?v=1704085395&amp;width=200" alt="panabit.webp?v=1704085395&amp;width=200"></th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody><tbody><tr><td>## 常见问题1.如何进入R1的BIOS后台？&gt; 通电开机后，0.5秒内按下<code>F2</code>即可进入BIOS后台，0.5秒内按下<code>F12</code>即可进入启动项选择界面。2.如何设置来电自启和手动开关机?&gt; 通电开机的0.5秒内按下F2进入BIOS后台，然后在路径<code>Chipset</code>&gt;&gt;&gt;<code>PCH-IO Configuration</code>&gt;&gt;&gt;<code>State After G3</code>下设置：<code>S0 State</code>为来电自启 ；<code>S5 State</code></td><td>为手动开关机。3.如何解锁温度墙？&gt; 通电开机的0.5秒内按下F2进入BIOS后台，然后在路径<code>Advanced</code>&gt;&gt;&gt;<code>Thermal configuration</code>&gt;&gt;&gt;<code>CPU Thermal configuration</code>&gt;&gt;&gt;<code>Tcc of activation offset</code>下调整数值：默认是30，表示温度墙是105-30=75度；用户可以调整该数值。设置为0代表温度墙为105度，即没有温度墙；建议设置数值为15，即表示温度墙为105-15=90度，如果自行调整的温度墙上限较高，导致整机温度较高，烦请理解原因。 硬酷科技在此反馈高温烤机压力测试表现：硬酷R1在环境温度为65度的高温压力测试环境中，处理器温度高大90+，但是依然没有死机，最终降频通过测试。4.硬酷R1的硬盘支持NVMe和SATA自适应吗？&gt; 目前，只能二选一，默认为NVMe协议，如果用户需要使用速度稍低且发热较低的SATA协议的M.2 2242硬盘的话，用户需要参考 <a href="/#/20241006/zh/update">升级BIOS</a> ，进行刷写SATA协议的BIOS，反之，如果用户需要从SATA协议的BIOS中回到NVMe协议的 BIOS，也需要进行BIOS刷写。 ⚠️温馨提示：刷写BIOS为高阶风险操作，用户需要自行承担风险。5.如何给硬酷R1刷写BIOS？&gt; 参考 [<a href="https://wiki.ikoolcore.com/#/v1.2/zh/update">升级BIOS]</a> 。6.硬酷R1支持传统的引导方式吗？&gt; 目前，Intel 10代以后的处理器，均只支持UEFI引导，所有不支持UEFI引导的固件，均无法物理直装的方式安装在硬酷R1上。解决办法也是有的：借助PVE虚拟机或者ESXi虚拟机。此类系统有：Panabit等。7.硬酷R1上的TF卡支持引导启动吗？&gt; 支持。注意：Linux及其分支均(<code>OpenWRT, pfsense, OPNSense</code>)可启动，Windows往TF卡写启动盘时，需用<a href="https://rufus.ie/downloads/">rufus</a>软件写入<code>WinToGo</code>启动盘。8.硬酷R1电源规格是？&gt; 在 <a href="/#/20241006/zh/r1">硬件设计</a> 中，明确表示：硬酷R1上带有PD标识的Type-C口，同时支持DC 12/20和PD双协议（优先协商到20V，后协商到12V），正因为使用了双供电协议，所以无法采用DC圆头形态的电源接口。但硬酷科技为所有订单标配了DC母头转C口公头的转接线，用户依然可以使用其已有的DC 12V圆头电源为R1提供电力</td></tr></tbody></table>',14),s=[d],r={__name:"r1",setup(i,{expose:t}){return t({frontmatter:{}}),(l,n)=>(e(),o("div",c,s))}};export{r as default};
